using OsbKT;

namespace Osb.Shell.Userspace
{
    internal static unsafe partial class Program
    {
        // Version metadata loaded from /OSB/CONF/VERSION.JSON (generated by
        // osb.kernel/scripts/generate-metadata.cake). No hardcoded version or
        // codename table is kept here: the values come from the generated
        // artifact. The small fixed fallbacks below only apply when the
        // artifact is absent so the shell stays bootable; a missing artifact
        // is reported by the build, not silently trusted.
        private struct VersionEntry
        {
            public fixed char component[32];
            public fixed char version[32];
            public int generation;
            public fixed char codename[32];
            public bool valid;
        }

        private static VersionEntry* _versions;
        private static int _versionCount;
        private static bool _versionsLoaded;

        // Size of VersionEntry struct (calculated manually for freestanding)
        private const int VersionEntrySize = 32 * 2 + 4 + 32 * 2 + 1; // component(64) + version(64) + generation(4) + codename(64) + valid(1) = 197, padded

        // Load version metadata from /OSB/CONF/VERSION.JSON
        private static void LoadVersions()
        {
            if (_versionsLoaded) return;
            _versionsLoaded = true;

            // Build path manually to avoid foreach on string
            var pathBuf = stackalloc byte[256];
            int plen = 0;
            fixed (char* p = "A:\\OSB\\CONF\\VERSION.JSON")
            {
                for (int k = 0; k < 23; k++) pathBuf[plen++] = (byte)p[k];
            }

            int h = Syscall.Open(pathBuf, plen);
            if (h < 0)
            {
                // Metadata not available; fall back to defaults
                _versions = null;
                _versionCount = 0;
                return;
            }

            // Read entire file
            var fileBuf = stackalloc byte[2048];
            int total = 0;
            for (;;)
            {
                int got = Syscall.Read(h, fileBuf + total, 512);
                if (got <= 0) break;
                total += got;
                if (total >= 2048) break;
            }
            Syscall.Close(h);

            if (total == 0)
            {
                _versions = null;
                _versionCount = 0;
                return;
            }

            // Count lines
            int lines = 0;
            for (int i = 0; i < total; i++)
                if (fileBuf[i] == (byte)'\n') lines++;

            byte* versionsRaw = stackalloc byte[lines * VersionEntrySize];
            _versions = (VersionEntry*)versionsRaw;
            _versionCount = 0;

            // Parse lines: component:version:generation:codename
            int lineStart = 0;
            for (int i = 0; i <= total; i++)
            {
                if (i == total || fileBuf[i] == (byte)'\n')
                {
                    int lineLen = i - lineStart;
                    if (lineLen > 0)
                    {
                        VersionEntry entry;
                        ParseVersionLine(fileBuf, lineStart, lineLen, out entry);
                        if (entry.valid)
                        {
                            _versions[_versionCount] = entry;
                            _versionCount++;
                        }
                    }
                    lineStart = i + 1;
                }
            }
        }

        private static void ParseVersionLine(byte* buf, int start, int len, out VersionEntry entry)
        {
            entry = default;
            entry.valid = false;

            // Find component (before first :)
            int p = start;
            int compEnd = p;
            while (compEnd < start + len && buf[compEnd] != (byte)':') compEnd++;
            if (compEnd >= start + len) return;
            int compLen = compEnd - p;
            if (compLen >= 32) compLen = 31;
            for (int k = 0; k < compLen; k++) entry.component[k] = (char)buf[p + k];

            // Find version (between first and second :)
            p = compEnd + 1;
            int verEnd = p;
            while (verEnd < start + len && buf[verEnd] != (byte)':') verEnd++;
            if (verEnd >= start + len) return;
            int verLen = verEnd - p;
            if (verLen >= 32) verLen = 31;
            for (int k = 0; k < verLen; k++) entry.version[k] = (char)buf[p + k];

            // Find generation (between second and third :)
            p = verEnd + 1;
            int genEnd = p;
            while (genEnd < start + len && buf[genEnd] != (byte)':') genEnd++;
            if (genEnd >= start + len) return;
            int genVal = 0;
            for (int k = p; k < genEnd; k++)
            {
                char c = (char)buf[k];
                if (c >= '0' && c <= '9') genVal = genVal * 10 + (c - '0');
            }
            entry.generation = genVal;

            // Codename (rest of line)
            p = genEnd + 1;
            int nameLen = start + len - p;
            if (nameLen > 0 && buf[start + len - 1] == (byte)'\r') nameLen--; // handle CRLF
            if (nameLen >= 32) nameLen = 31;
            for (int k = 0; k < nameLen; k++) entry.codename[k] = (char)buf[p + k];

            entry.valid = true;
        }

        // Get version string for a component (component name as fixed char*)
        private static void GetVersionString(char* component, char* outBuf, int cap, out int outLen)
        {
            outLen = 0;
            LoadVersions();

            if (_versions == null)
            {
                // Fallback defaults (used only when the artifact is absent)
                fixed (char* kernel = "osb.kernel")
                fixed (char* shell = "osb.shell")
                fixed (char* core = "osb.core")
                fixed (char* toolkit = "osbkt")
                fixed (char* oslang = "osb.oslang")
                fixed (char* v010 = "0.1.0")
                fixed (char* v080 = "0.8.0")
                fixed (char* v000 = "0.0.0")
                {
                    char* fallbackStr;
                    int fallbackLen;
                    if (StrEqualsPtr(component, kernel)) { fallbackStr = v010; fallbackLen = 5; }
                    else if (StrEqualsPtr(component, shell)) { fallbackStr = v010; fallbackLen = 5; }
                    else if (StrEqualsPtr(component, core)) { fallbackStr = v010; fallbackLen = 5; }
                    else if (StrEqualsPtr(component, toolkit)) { fallbackStr = v010; fallbackLen = 5; }
                    else if (StrEqualsPtr(component, oslang)) { fallbackStr = v080; fallbackLen = 5; }
                    else { fallbackStr = v000; fallbackLen = 5; }
                    for (int k = 0; k < fallbackLen && k < cap - 1; k++) outBuf[k] = fallbackStr[k];
                    outLen = fallbackLen;
                }
                return;
            }

            for (int i = 0; i < _versionCount; i++)
            {
                var e = _versions[i];
                if (ComponentMatchesPtr(e, component))
                {
                    // Found matching component, copy version
                    int k = 0;
                    while (k < 32 && e.version[k] != '\0' && k < cap - 1)
                    {
                        outBuf[k] = e.version[k];
                        k++;
                    }
                    outLen = k;
                    return;
                }
            }

            // Not found, use fallback
            fixed (char* fb = "0.0.0")
            {
                for (int k = 0; k < 5 && k < cap - 1; k++) outBuf[k] = fb[k];
                outLen = 5;
            }
        }

        private static bool ComponentMatchesPtr(VersionEntry e, char* component)
        {
            for (int k = 0; k < 32; k++)
            {
                char ec = e.component[k];
                char cc = component[k];
                if (ec == '\0' && cc == '\0') return true;
                if (ec != cc) return false;
            }
            return true;
        }

        private static bool StrEqualsPtr(char* a, char* b)
        {
            for (int k = 0; k < 32; k++)
            {
                char ca = a[k];
                char cb = b[k];
                if (ca == '\0' && cb == '\0') return true;
                if (ca != cb) return false;
            }
            return true;
        }

        // Get codename for generation 0
        private static void GetCodename(char* outBuf, int cap, out int outLen)
        {
            outLen = 0;
            LoadVersions();

            if (_versions == null)
            {
                fixed (char* fallback = "Olorun")
                {
                    for (int k = 0; k < 6 && k < cap - 1; k++) outBuf[k] = fallback[k];
                    outLen = 6;
                }
                return;
            }

            for (int i = 0; i < _versionCount; i++)
            {
                var e = _versions[i];
                if (e.generation == 0 && e.codename[0] != '\0')
                {
                    int k = 0;
                    while (k < 32 && e.codename[k] != '\0' && k < cap - 1)
                    {
                        outBuf[k] = e.codename[k];
                        k++;
                    }
                    outLen = k;
                    return;
                }
            }

            fixed (char* fb = "Olorun")
            {
                for (int k = 0; k < 6 && k < cap - 1; k++) outBuf[k] = fb[k];
                outLen = 6;
            }
        }
    }
}